import json, urllib.request, ssl, time

ctx = ssl._create_unverified_context()
headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer $thehive_api_key"
}

def thehive_post(path, body):
    req = urllib.request.Request(
        f"$thehive_url{path}",
        data=json.dumps(body).encode(),
        headers=headers,
        method="POST"
    )
    resp = urllib.request.urlopen(req, context=ctx, timeout=15)
    return json.loads(resp.read().decode())

errors = []
cases = []

try:
    ten_min_ago_ms = int((time.time() - 600) * 1000)

    # Query cases created in last 10 min with tier1_ti_match tag
    query_body = {
        "query": [
            {"_name": "listCase"},
            {"_name": "filter", "_and": [
                {"_gte": {"_field": "_createdAt", "_value": ten_min_ago_ms}},
                {"_in": {"_field": "tags", "_values": ["tier1_ti_match"]}}
            ]},
            {"_name": "sort", "_fields": [{"_createdAt": "desc"}]},
            {"_name": "page", "from": 0, "to": 50}
        ]
    }

    result = thehive_post("/api/v1/query", query_body)
    if not isinstance(result, list):
        result = []

    for case in result:
        case_id = case.get("_id", "")
        title = case.get("title", "")
        tags = case.get("tags", [])

        # Check if case already has observables (skip if enriched)
        try:
            obs_query = {
                "query": [
                    {"_name": "getCase", "idOrName": case_id},
                    {"_name": "observables"},
                    {"_name": "page", "from": 0, "to": 1}
                ]
            }
            obs_result = thehive_post("/api/v1/query", obs_query)
            has_observables = len(obs_result) > 0 if isinstance(obs_result, list) else False
        except:
            has_observables = False

        if not has_observables:
            cases.append({
                "case_id": case_id,
                "title": str(title).replace('"', "'").replace("\\", "")[:300],
                "tags": tags if isinstance(tags, list) else []
            })

except Exception as e:
    errors.append(str(e)[:200])

print(json.dumps({
    "cases": cases,
    "case_count": len(cases),
    "errors": errors
}))

import json, urllib.request, ssl

upstream = json.loads('''$filter_and_extract.message''')
if isinstance(upstream, str):
    try:
        upstream = json.loads(upstream)
    except:
        upstream = {}

enrichments = upstream.get("enrichments", [])

ctx = ssl._create_unverified_context()
headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer $thehive_api_key"
}

results = []
errors = []

for enr in enrichments:
    case_id = enr.get("case_id", "")
    obs_type = enr.get("observable_type", "")
    obs_value = enr.get("observable_value", "")
    analyzers = enr.get("analyzers", [])

    artifact_body = {
        "dataType": obs_type,
        "data": obs_value,
        "message": f"Auto-created by WF-HACCP-1.1 for Cortex enrichment ({obs_type})",
        "tlp": 2,
        "tags": ["wf-haccp-1.1", "auto-enrichment"]
    }

    try:
        req = urllib.request.Request(
            f"$thehive_url/api/case/{case_id}/artifact",
            data=json.dumps(artifact_body).encode(),
            headers=headers,
            method="POST"
        )
        resp = urllib.request.urlopen(req, context=ctx, timeout=15)
        created = json.loads(resp.read().decode())

        # TheHive 4 returns list for artifact creation
        if isinstance(created, list) and len(created) > 0:
            artifact_id = created[0].get("_id") or created[0].get("id", "")
        elif isinstance(created, dict):
            artifact_id = created.get("_id") or created.get("id", "")
        else:
            artifact_id = ""

        results.append({
            "case_id": case_id,
            "artifact_id": artifact_id,
            "observable_type": obs_type,
            "observable_value": obs_value,
            "analyzers": analyzers,
            "status": "created"
        })
    except Exception as e:
        errors.append({
            "case_id": case_id,
            "observable_value": obs_value,
            "error": str(e)[:200]
        })

print(json.dumps({
    "observables": results,
    "observable_count": len(results),
    "errors": errors
}))

import json, urllib.request, ssl

upstream = json.loads('''$create_observables.message''')
if isinstance(upstream, str):
    try:
        upstream = json.loads(upstream)
    except:
        upstream = {}

observables = upstream.get("observables", [])

ctx = ssl._create_unverified_context()
thehive_headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer $thehive_api_key"
}

jobs = []
errors = []

for obs in observables:
    artifact_id = obs.get("artifact_id", "")
    analyzers = obs.get("analyzers", [])
    case_id = obs.get("case_id", "")
    obs_type = obs.get("observable_type", "")
    obs_value = obs.get("observable_value", "")

    if not artifact_id:
        errors.append({"case_id": case_id, "error": "no artifact_id, skipping analyzers"})
        continue

    for analyzer_name in analyzers:
        # Try TheHive Cortex connector first (preferred path)
        job_body = {
            "cortexId": "local",
            "artifactId": artifact_id,
            "analyzerId": analyzer_name
        }
        try:
            req = urllib.request.Request(
                "$thehive_url/api/connector/cortex/job",
                data=json.dumps(job_body).encode(),
                headers=thehive_headers,
                method="POST"
            )
            resp = urllib.request.urlopen(req, context=ctx, timeout=15)
            result = json.loads(resp.read().decode())
            job_id = result.get("_id") or result.get("id", "")
            jobs.append({
                "case_id": case_id,
                "artifact_id": artifact_id,
                "analyzer": analyzer_name,
                "job_id": job_id,
                "method": "thehive_connector",
                "status": "submitted"
            })
        except Exception as e:
            # Fallback: direct Cortex API
            cortex_headers = {
                "Content-Type": "application/json",
                "Authorization": "Bearer $cortex_api_key"
            }
            cortex_body = {
                "data": obs_value,
                "dataType": obs_type,
                "tlp": 2,
                "parameters": {}
            }
            try:
                fb_req = urllib.request.Request(
                    f"$cortex_url/api/analyzer/{analyzer_name}/run",
                    data=json.dumps(cortex_body).encode(),
                    headers=cortex_headers,
                    method="POST"
                )
                fb_resp = urllib.request.urlopen(fb_req, context=ctx, timeout=15)
                fb_result = json.loads(fb_resp.read().decode())
                fb_job_id = fb_result.get("_id") or fb_result.get("id", "")
                jobs.append({
                    "case_id": case_id,
                    "artifact_id": artifact_id,
                    "analyzer": analyzer_name,
                    "job_id": fb_job_id,
                    "method": "cortex_direct",
                    "status": "submitted"
                })
            except Exception as e2:
                errors.append({
                    "case_id": case_id,
                    "analyzer": analyzer_name,
                    "thehive_error": str(e)[:150],
                    "cortex_error": str(e2)[:150]
                })

print(json.dumps({
    "jobs": jobs,
    "job_count": len(jobs),
    "errors": errors
}))
